-- PostgreSQL design target. This is NOT the JSON demo persistence adapter.
-- Apply to an empty development database after review; no DROP statements.
BEGIN;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL);
CREATE TABLE sites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,code text NOT NULL,name text NOT NULL,UNIQUE(organization_id,code));
CREATE TABLE warehouses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,code text NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(site_id,code));
CREATE TABLE app_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,subject_id text NOT NULL UNIQUE,display_name text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE);
CREATE TABLE user_roles(user_id uuid REFERENCES app_users,role_id uuid REFERENCES roles,PRIMARY KEY(user_id,role_id));
CREATE TABLE user_scopes(user_id uuid REFERENCES app_users,site_id uuid REFERENCES sites,warehouse_id uuid REFERENCES warehouses,PRIMARY KEY(user_id,site_id,warehouse_id));
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,code text NOT NULL,name text NOT NULL,UNIQUE(organization_id,code));
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,code text NOT NULL,name text NOT NULL,UNIQUE(organization_id,code));
CREATE TABLE units(code text PRIMARY KEY,name text NOT NULL,dimension text NOT NULL CHECK(dimension IN('MASS','VOLUME','COUNT','PORTION')));
CREATE TABLE item_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,code text NOT NULL,name text NOT NULL,UNIQUE(organization_id,code));
CREATE TABLE items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,category_id uuid REFERENCES item_categories,code text NOT NULL,name text NOT NULL,base_unit text NOT NULL REFERENCES units,active boolean NOT NULL DEFAULT true,UNIQUE(organization_id,code));
CREATE TABLE item_unit_conversions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),item_id uuid NOT NULL REFERENCES items,from_unit text NOT NULL REFERENCES units,to_unit text NOT NULL REFERENCES units,factor numeric(20,8) NOT NULL CHECK(factor>0),effective_from date NOT NULL,effective_to date,CHECK(effective_to IS NULL OR effective_to>effective_from),UNIQUE(item_id,from_unit,to_unit,effective_from));
CREATE TABLE warehouse_items(warehouse_id uuid REFERENCES warehouses,item_id uuid REFERENCES items,safety_quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK(safety_quantity>=0),purchase_pack_base numeric(20,6) NOT NULL DEFAULT 1 CHECK(purchase_pack_base>0),PRIMARY KEY(warehouse_id,item_id));
CREATE TABLE contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers,code text NOT NULL,effective_from date NOT NULL,effective_to date,CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE contract_prices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid NOT NULL REFERENCES contracts,shift text NOT NULL CHECK(shift IN('SANG','TRUA','CHIEU','XE')),meal_group text NOT NULL,valid_from date NOT NULL,valid_to date,unit_price numeric(20,2) NOT NULL CHECK(unit_price>=0),billing_basis text NOT NULL CHECK(billing_basis IN('CONFIRMED','DELIVERED','ACCEPTED')),CHECK(valid_to IS NULL OR valid_to>valid_from),UNIQUE(contract_id,shift,meal_group,valid_from));
-- Prevent overlapping effective ranges in the application transaction or add a reviewed
-- btree_gist exclusion constraint. The UNIQUE above alone does NOT prevent overlaps.
CREATE TABLE dishes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,code text NOT NULL,name text NOT NULL,UNIQUE(organization_id,code));
CREATE TABLE dish_aliases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,source_system text NOT NULL,alias_name text NOT NULL,dish_id uuid NOT NULL REFERENCES dishes,approved_by uuid REFERENCES app_users,UNIQUE(organization_id,source_system,alias_name));
CREATE TABLE recipe_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dish_id uuid NOT NULL REFERENCES dishes,version integer NOT NULL CHECK(version>0),effective_from date NOT NULL,effective_to date,status text NOT NULL CHECK(status IN('DRAFT','APPROVED','RETIRED')),quantity_basis text NOT NULL CHECK(quantity_basis IN('PER_SERVING','PER_BATCH')),yield_quantity numeric(20,6) NOT NULL CHECK(yield_quantity>0),yield_unit text NOT NULL REFERENCES units,UNIQUE(dish_id,version),UNIQUE(id,dish_id),CHECK(effective_to IS NULL OR effective_to>effective_from));
CREATE TABLE recipe_ingredients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipe_version_id uuid NOT NULL REFERENCES recipe_versions,line_no integer NOT NULL CHECK(line_no>0),component_type text NOT NULL CHECK(component_type IN('ITEM','SUBRECIPE','AUXILIARY')),item_id uuid REFERENCES items,child_recipe_version_id uuid REFERENCES recipe_versions,quantity numeric(20,6) NOT NULL CHECK(quantity>=0),unit_code text NOT NULL REFERENCES units,weight_basis text NOT NULL CHECK(weight_basis IN('RAW','COOKED')),yield_rate numeric(10,6) CHECK(yield_rate>0),CHECK((component_type='ITEM' AND item_id IS NOT NULL AND child_recipe_version_id IS NULL) OR (component_type='SUBRECIPE' AND item_id IS NULL AND child_recipe_version_id IS NOT NULL) OR (component_type='AUXILIARY' AND item_id IS NULL AND child_recipe_version_id IS NULL)),CHECK(weight_basis='RAW' OR yield_rate IS NOT NULL),UNIQUE(recipe_version_id,line_no));
-- A graph cycle in child_recipe_version_id must also be rejected by BE before approval.
CREATE TABLE meal_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,customer_id uuid NOT NULL REFERENCES customers,service_date date NOT NULL,shift text NOT NULL CHECK(shift IN('SANG','TRUA','CHIEU','XE')),current_version integer NOT NULL DEFAULT 1,UNIQUE(site_id,customer_id,service_date,shift));
CREATE TABLE meal_plan_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),meal_plan_id uuid NOT NULL REFERENCES meal_plans,version integer NOT NULL CHECK(version>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED','SUPERSEDED')),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES app_users,reason text,UNIQUE(meal_plan_id,version));
CREATE TABLE meal_plan_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_version_id uuid NOT NULL REFERENCES meal_plan_versions,meal_group text NOT NULL,reported_servings integer NOT NULL CHECK(reported_servings>=0),production_servings integer NOT NULL CHECK(production_servings>=0),replacement_servings integer NOT NULL DEFAULT 0 CHECK(replacement_servings>=0),replacement_included boolean NOT NULL DEFAULT true,CHECK(NOT replacement_included OR replacement_servings<=reported_servings),UNIQUE(plan_version_id,meal_group));
CREATE TABLE menu_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,customer_id uuid NOT NULL REFERENCES customers,service_date date NOT NULL,shift text NOT NULL,version integer NOT NULL CHECK(version>0),status text NOT NULL CHECK(status IN('DRAFT','APPROVED','SUPERSEDED')),UNIQUE(site_id,customer_id,service_date,shift,version));
CREATE TABLE menu_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),menu_version_id uuid NOT NULL REFERENCES menu_versions,slot text NOT NULL,meal_group text NOT NULL,dish_id uuid NOT NULL REFERENCES dishes,recipe_version_id uuid NOT NULL,serving_rule text NOT NULL,FOREIGN KEY(recipe_version_id,dish_id) REFERENCES recipe_versions(id,dish_id),UNIQUE(menu_version_id,meal_group,slot));
CREATE TABLE requirement_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,plan_version_id uuid NOT NULL REFERENCES meal_plan_versions,menu_version_id uuid NOT NULL REFERENCES menu_versions,status text NOT NULL CHECK(status IN('READY','STALE','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES app_users);
CREATE TABLE requirement_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES requirement_runs,warehouse_id uuid NOT NULL REFERENCES warehouses,item_id uuid NOT NULL REFERENCES items,required_base_quantity numeric(20,6) NOT NULL CHECK(required_base_quantity>=0),UNIQUE(run_id,warehouse_id,item_id));
CREATE TABLE requirement_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_line_id uuid NOT NULL REFERENCES requirement_lines,menu_line_id uuid NOT NULL REFERENCES menu_lines,ingredient_id uuid NOT NULL REFERENCES recipe_ingredients,applicable_servings integer NOT NULL CHECK(applicable_servings>=0),quantity_per_serving_snapshot numeric(20,6) NOT NULL CHECK(quantity_per_serving_snapshot>=0),conversion_factor_snapshot numeric(20,8) NOT NULL CHECK(conversion_factor_snapshot>0),required_base_quantity numeric(20,6) NOT NULL CHECK(required_base_quantity>=0),source_path jsonb NOT NULL DEFAULT '[]');
CREATE TABLE stock_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_line_id uuid NOT NULL REFERENCES requirement_lines,warehouse_id uuid NOT NULL REFERENCES warehouses,item_id uuid NOT NULL REFERENCES items,quantity numeric(20,6) NOT NULL CHECK(quantity>0),status text NOT NULL CHECK(status IN('ACTIVE','CONSUMED','RELEASED')));
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,supplier_id uuid NOT NULL REFERENCES suppliers,code text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN('DRAFT','APPROVED','PARTIAL','RECEIVED','CANCELLED')),needed_at timestamptz NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE TABLE purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES purchase_orders,requirement_line_id uuid REFERENCES requirement_lines,item_id uuid NOT NULL REFERENCES items,ordered_base_quantity numeric(20,6) NOT NULL CHECK(ordered_base_quantity>0),unit_price_base numeric(20,6) NOT NULL CHECK(unit_price_base>=0),received_base_quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK(received_base_quantity>=0),CHECK(received_base_quantity<=ordered_base_quantity));
CREATE TABLE goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,supplier_id uuid NOT NULL REFERENCES suppliers,code text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN('DRAFT','POSTED','REVERSED')),received_at timestamptz NOT NULL,posted_at timestamptz);
CREATE TABLE goods_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_id uuid NOT NULL REFERENCES goods_receipts,order_line_id uuid REFERENCES purchase_order_lines,item_id uuid NOT NULL REFERENCES items,warehouse_id uuid NOT NULL REFERENCES warehouses,accepted_quantity numeric(20,6) NOT NULL CHECK(accepted_quantity>0),rejected_quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK(rejected_quantity>=0),actual_unit_cost numeric(20,6) NOT NULL CHECK(actual_unit_cost>=0));
CREATE TABLE stock_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,code text NOT NULL UNIQUE,document_type text NOT NULL CHECK(document_type IN('RECEIPT','ISSUE','RETURN','TRANSFER','ADJUSTMENT','REVERSAL')),status text NOT NULL CHECK(status IN('DRAFT','APPROVED','POSTED','REVERSED')),effective_at timestamptz NOT NULL,posted_at timestamptz,posted_by uuid REFERENCES app_users,reason text,revision integer NOT NULL DEFAULT 1);
CREATE TABLE stock_document_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES stock_documents,item_id uuid NOT NULL REFERENCES items,source_warehouse_id uuid REFERENCES warehouses,target_warehouse_id uuid REFERENCES warehouses,requested_quantity numeric(20,6) CHECK(requested_quantity>=0),approved_quantity numeric(20,6) CHECK(approved_quantity>=0),actual_quantity numeric(20,6) NOT NULL CHECK(actual_quantity>0),unit_cost_snapshot numeric(20,6) NOT NULL CHECK(unit_cost_snapshot>=0),receipt_line_id uuid REFERENCES goods_receipt_lines,requirement_line_id uuid REFERENCES requirement_lines,CHECK(source_warehouse_id IS NOT NULL OR target_warehouse_id IS NOT NULL),CHECK(source_warehouse_id IS NULL OR target_warehouse_id IS NULL OR source_warehouse_id<>target_warehouse_id));
CREATE TABLE inventory_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_document_line_id uuid NOT NULL REFERENCES stock_document_lines,warehouse_id uuid NOT NULL REFERENCES warehouses,item_id uuid NOT NULL REFERENCES items,effective_at timestamptz NOT NULL,posted_at timestamptz NOT NULL DEFAULT now(),quantity_delta numeric(20,6) NOT NULL CHECK(quantity_delta<>0),value_delta numeric(20,6) NOT NULL,reversal_of_entry_id uuid UNIQUE REFERENCES inventory_entries,UNIQUE(source_document_line_id,warehouse_id));
CREATE TABLE inventory_balances(warehouse_id uuid REFERENCES warehouses,item_id uuid REFERENCES items,quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK(quantity>=0),value numeric(20,6) NOT NULL DEFAULT 0 CHECK(value>=0),revision bigint NOT NULL DEFAULT 1,PRIMARY KEY(warehouse_id,item_id));
CREATE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'Posted ledger is immutable. Insert reversal entries.';END;$$;
CREATE TRIGGER inventory_entries_immutable BEFORE UPDATE OR DELETE ON inventory_entries FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
CREATE TABLE stock_counts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id uuid NOT NULL REFERENCES warehouses,counted_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('DRAFT','APPROVED','POSTED')),adjustment_document_id uuid REFERENCES stock_documents);
CREATE TABLE stock_count_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),count_id uuid NOT NULL REFERENCES stock_counts,item_id uuid NOT NULL REFERENCES items,book_quantity_snapshot numeric(20,6) NOT NULL,counted_quantity numeric(20,6) NOT NULL CHECK(counted_quantity>=0),UNIQUE(count_id,item_id));
CREATE TABLE meal_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_version_id uuid NOT NULL REFERENCES meal_plan_versions,delivered_servings integer NOT NULL CHECK(delivered_servings>=0),accepted_servings integer CHECK(accepted_servings>=0),receiver_name text NOT NULL,confirmed_at timestamptz);
CREATE TABLE billing_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers,plan_version_id uuid NOT NULL REFERENCES meal_plan_versions,delivery_id uuid REFERENCES meal_deliveries,billing_basis text NOT NULL CHECK(billing_basis IN('CONFIRMED','DELIVERED','ACCEPTED')),billable_servings integer NOT NULL CHECK(billable_servings>=0),unit_price_snapshot numeric(20,2) NOT NULL CHECK(unit_price_snapshot>=0),amount numeric(20,2) GENERATED ALWAYS AS (billable_servings*unit_price_snapshot) STORED,status text NOT NULL CHECK(status IN('DRAFT','APPROVED','ADJUSTED')));
CREATE TABLE expense_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,expense_date date NOT NULL,category text NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount>0),note text NOT NULL,status text NOT NULL CHECK(status IN('DRAFT','APPROVED')));
CREATE TABLE import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,source_name text NOT NULL,file_hash text NOT NULL,mapping_version text NOT NULL,base_menu_version_id uuid REFERENCES menu_versions,status text NOT NULL CHECK(status IN('PREVIEW','INVALID','COMMITTED','CANCELLED')),created_by uuid NOT NULL REFERENCES app_users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_rows(batch_id uuid REFERENCES import_batches,row_number integer NOT NULL CHECK(row_number>0),raw_data jsonb NOT NULL,normalized_data jsonb,errors jsonb NOT NULL DEFAULT '[]',PRIMARY KEY(batch_id,row_number));
CREATE TABLE idempotency_requests(actor_id uuid NOT NULL REFERENCES app_users,request_key uuid NOT NULL,endpoint text NOT NULL,payload_hash text NOT NULL,response_status integer NOT NULL,response_body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,request_key));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES app_users,action text NOT NULL,entity_type text NOT NULL,entity_id uuid,at timestamptz NOT NULL DEFAULT now(),before_data jsonb,after_data jsonb,request_key uuid);
CREATE TABLE period_closes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid NOT NULL REFERENCES sites,closed_through date NOT NULL,closed_by uuid NOT NULL REFERENCES app_users,closed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legacy_import_map(entity_type text NOT NULL,source_system text NOT NULL,legacy_id text NOT NULL,target_uuid uuid NOT NULL,PRIMARY KEY(entity_type,source_system,legacy_id));
CREATE INDEX inventory_entries_lookup ON inventory_entries(warehouse_id,item_id,effective_at);
CREATE INDEX requirement_sources_trace ON requirement_sources(requirement_line_id);
CREATE INDEX purchase_orders_due ON purchase_orders(site_id,status,needed_at);
CREATE INDEX menu_versions_day ON menu_versions(site_id,service_date,shift,status);
CREATE INDEX audit_entity ON audit_logs(entity_type,entity_id,at);
COMMIT;
